def fig_levels():
    o=''
    data=((4,52,'0','2D сызба,\nқағаз','bx'),(88,72,'1','2D/3D CAD,\nортақ қойма','bx'),(172,98,'2','әр сала өз\n3D моделі,\nIFC арқылы','soft'),(256,124,'3','бір ортақ\nмодель,\nбұлтта','bxa'))
    for x,h,n,t,c in data:
        y=150-h;o+=R(x,y,80,h,c,6)+T(x+40,y+16,'Деңгей '+n,'t-s t-b')
        for i,line in enumerate(t.split('\n')):o+=T(x+40,y+32+i*13,line,'t-s')
    o+=L(4,150,336,150)+TL(4,172,'Деңгей өскен сайын бірлесіп жұмыс жақсарады','t-s mu')
    return S(340,180,o,'BIM жетілу деңгейлері 0–3')
