    o+=A(95,64,95,34)+A(245,64,245,34)
    o+=B(4,156,120,44,'BIM моделі\n(геометрия, ID)','bx','t-s',lh=14)+B(216,156,120,44,'Ғимарат: ҒАБЖ,\nIoT (БЛК, датчик)','bxa','t-s',lh=14)
